package you.v50to.eatwhat.control;

import java.nio.channels.FileChannel;
import java.nio.file.*;
import java.nio.file.attribute.PosixFilePermissions;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Immutable local witness for the TARGET's exact pre-Docker services baseline.
 * Written once after actual profile/cache application inside its authority
 * fence. Missing evidence is never regenerated by read-only status. Native
 * verification still checks all original services, files and network proofs. */
public final class ControlBootstrapProfileServices {
    private ControlBootstrapProfileServices(){}
    static final String PROTOCOL="eatwhat-controller-profile-services-successor-v1";
    static final String RUNTIME_PROTOCOL="eatwhat-controller-profile-services-runtime-v1";
    private static Path path(ControlBootstrapProfileState.Accepted a){return Path.of(a.plans().target().profilesFile()).getParent()
            .resolve("profile-publications").resolve(a.frozen().spec().targetServerId().toString()).resolve("services-successor.json");}
    private static Map<String,Object> witness(ControlBootstrapProfileState.Accepted a){
        var fields=new LinkedHashMap<String,Object>();fields.put("protocol",PROTOCOL);fields.put("bootstrapId",a.frozen().spec().id().toString());fields.put("serverId",a.frozen().spec().targetServerId().toString());
        fields.put("approvalDigest",a.approvalDigest());fields.put("businessJobId",a.services().businessJobId().toString());fields.put("businessBinding",a.services().businessBinding());
        fields.put("baselineSha256",a.services().baselineSha256());fields.put("controllerBinding",a.services().controllerBinding());fields.put("acceptanceBinding",a.binding());
        fields.put("profilePlanBinding",a.plans().target().binding());fields.put("controllerId",a.targetControllerId().toString());fields.put("applicationSha256",a.targetApplicationSha256());
        fields.put("nodeTokenFile",a.bridge().targetTokenFile());fields.put("joinAuthorized",false);
        return sign(a,fields);
    }
    private static Map<String,Object> sign(ControlBootstrapProfileState.Accepted a,Map<String,Object> body){
        try{
            byte[] key=ControlAudit.token(Path.of(a.bridge().targetTokenFile())).getBytes(StandardCharsets.US_ASCII);
            var mac=javax.crypto.Mac.getInstance("HmacSHA256");mac.init(new javax.crypto.spec.SecretKeySpec(key,"HmacSHA256"));
            var signed=new LinkedHashMap<>(body);signed.put("signature",Base64.getEncoder().encodeToString(mac.doFinal(ControlBootstrapNativeJson.encode(body).getBytes(StandardCharsets.US_ASCII))));return signed;
        }catch(Exception failure){throw new ControlFailure(409,"BOOTSTRAP_PROFILE_SERVICES_RECORD_CHANGED");}
    }
    static Map<String,Object> runtime(ControlBootstrapProfileState.Accepted a,Map<String,Object> observed){
        var fields=new LinkedHashMap<>(observed);fields.remove("signature");fields.put("protocol",RUNTIME_PROTOCOL);return sign(a,fields);
    }
    static void observe(ControlBootstrapProfileState.Accepted a){
        Path file=path(a);if(!Files.exists(file,LinkOption.NOFOLLOW_LINKS))throw new ControlFailure(409,"BOOTSTRAP_PROFILE_SERVICES_RECORD_MISSING");
        try{
            byte[] expected=ControlBootstrapNativeJson.encode(witness(a)).getBytes(StandardCharsets.US_ASCII);
            byte[] actual=ControlMemberConfiguration.privateBytes(file,8192);
            if(!java.security.MessageDigest.isEqual(expected,actual))throw new Exception();
        }catch(Exception failure){throw new ControlFailure(409,"BOOTSTRAP_PROFILE_SERVICES_RECORD_CHANGED");}
    }
    static void publish(ControlBootstrapProfileState.Accepted a){
        Path file=path(a);try{
            for(Path p=file;p!=null;p=p.getParent())if(Files.isSymbolicLink(p))throw new Exception();
            byte[] raw=ControlBootstrapNativeJson.encode(witness(a)).getBytes(StandardCharsets.US_ASCII);
            try(var channel=FileChannel.open(file,Set.of(StandardOpenOption.WRITE,StandardOpenOption.CREATE_NEW,LinkOption.NOFOLLOW_LINKS),PosixFilePermissions.asFileAttribute(PosixFilePermissions.fromString("rw-------")))){
                var data=java.nio.ByteBuffer.wrap(raw);while(data.hasRemaining())channel.write(data);channel.force(true);
            }
            try(var directory=FileChannel.open(file.getParent(),StandardOpenOption.READ)){directory.force(true);}
            observe(a);
        }catch(ControlFailure failure){throw failure;}catch(Exception failure){throw new ControlFailure(409,"BOOTSTRAP_PROFILE_SERVICES_RECORD_CHANGED");}
    }
}
